solutions.naive:
class Solution:
    def maxConsecutiveAnswers(self, answerKey: str, k: int) -> int:
        n = len(answerKey)
        ans = 0
        for i in range(n):
            for j in range(i, n):
                t = 0
                f = 0
                for p in range(i, j + 1):
                    if answerKey[p] == 'T':
                        t += 1
                    else:
                        f += 1
                if min(t, f) <= k:
                    ans = max(ans, j - i + 1)
        return ans

