class Solution:
    def maxConsecutiveAnswers(self, answerKey: str, k: int) -> int:
        def longest(target: str) -> int:
            left = 0
            flips = 0
            best = 0
            for right, ch in enumerate(answerKey):
                if ch != target:
                    flips += 1
                while flips > k:
                    if answerKey[left] != target:
                        flips -= 1
                    left += 1
                best = max(best, right - left + 1)
            return best
        return max(longest('T'), longest('F'))

